package glitch

import data.glitch_lib

# Detect hard-coded passwords in variables, attributes, and nested structures
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables (e.g., Chef attributes, Ansible vars)
    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    # Check if variable name suggests a password/secret field
    password_indicators := {"password", "secret", "key", "token", "credential", "passphrase"}
    contains_lower(var.name, password_indicators[_])

    # Check if the value is a hard-coded string (not a reference)
    var.value.ir_type == "String"
    not is_variable_reference(var.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded password - Avoid hard-coding credentials in code. (CWE-259)"
    }
}

# Detect hard-coded passwords in attributes (e.g., Ansible task attributes, Chef resource attributes)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attributes := glitch_lib.all_attributes(parent)
    attr := attributes[_]

    # Check if attribute name suggests a password/secret field
    password_indicators := {"password", "secret", "key", "token", "credential", "passphrase"}
    contains_lower(attr.name, password_indicators[_])

    # Check if the value is a hard-coded string (not a reference)
    attr.value.ir_type == "String"
    not is_variable_reference(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded password - Avoid hard-coding credentials in code. (CWE-259)"
    }
}

# Helper function to check if a string contains any of the given substrings (case-insensitive)
contains_lower(str, substr) {
    regex.match(sprintf("(?i).*%s.*", [substr]), str)
}

# Helper function to check if a value is a variable reference (not a hard-coded value)
is_variable_reference(value) {
    value.ir_type == "VariableReference"
} else {
    # Also check for function calls that might fetch secrets dynamically
    value.ir_type == "FunctionCall"
}

